            for(int k=0;k<2;k++){h.Attack();Steps(.7f);e.invincible=0;e.transform.position=h.Position+Vector2.right;}h.Attack();Steps(.55f);float before=e.health;e.Tick(.23f);yield return new WaitForSecondsRealtime(.38f);Check(e.health<before,"Ultimo Acorde aplica eco atrasado real depois do finalizador");
